import { useRef } from 'react'
import { Html } from '@react-three/drei'
import { Group } from 'three'

const ProjectItem = ({
    title = 'title',
    description = 'description',
    link = '#',
    path = '',
    focus=false,
    handlePan=(number: number) => {}
}) => {
    const htmlRef = useRef<HTMLDivElement>(null)
    const groupRef = useRef<Group>(null)

    return (
        <group position={[0, 0.5, 0]} ref={groupRef}>
            <Html center scale={20} zIndexRange={[999,0]} >  
                <div ref={htmlRef} style={{ display: focus ? 'flex' : "none", fontSize: 25, flexDirection: 'column', alignItems: 'center', margin: 10, textAlign: 'center'}}>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 70, width: 200 }}>
                        </div>
                    </div>     
                    <div className='dark' style={{ background: 'rgb(255,255,2550)', border: '1px solid black', borderRadius: 5, padding: 20, height: '200px', width: "300px"}}>
                        <div style={{ display: 'flex', width: '100%', justifyContent: "space-between", alignContent: "center" }}>
                            <div onClick={e => handlePan(1)} style={{ fontSize: "30px", cursor: 'pointer' }}>⇦</div>
                            <a href={link} target='_blank' style={{fontWeight: 'bold', marginRight: "10px", marginLeft: "10px"}}>{title}</a>
                            <div onClick={e => handlePan(-1)} style={{ backgroundColor: "hover:red", fontSize: "30px", cursor: 'pointer' }}>⇨</div>
                        </div>
                        <div style={{ marginTop: '20px' }}>{description}</div>
                    </div>
                    <br/>
                    <a style={{height: '50vh', width: 400, overflow: 'hidden', display: 'flex'}} href={link} target='_blank'>
                    </a>
                </div>
            </Html>
        </group>
    )
}

export default ProjectItem